 "content": "def transform(grid):
    """Fill the horizontal 3-mask from the common repeated tile, then mark
    the recurring diagonal checkpoints in the 2-patterns."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate the horizontal color-3 mask and clear it.
    mask_rows = [r for r in range(h) if all(v == 3 for v in grid[r])]
    if not mask_rows:
        return out
    top, bottom = min(mask_rows), max(mask_rows)
    for r in range(top, bottom + 1):
        out[r] = [0] * w

    # ARC tiles are four cells wide with a one-cell gap (five-cell pitch).
    tile_w, pitch = 4, 5
    bands = []
    r = 0
    while r < h:
        if top <= r <= bottom:
            r = bottom + 1
            continue
        if any(grid[r][c] == 2 for c in range(w)):
            start = r
            while r < h and not (top <= r <= bottom) and any(grid[r][c] == 2 for c in range(w)):
                r += 1
            bands.append((start, r))
        else:
            r += 1

    occupied = []
    for start, end in bands:
        slots = set()
        for slot in range((w + pitch - 1) // pitch):
            c0 = slot * pitch
            if any(grid[rr][cc] == 2 for rr in range(start, end)
                   for cc in range(c0, min(c0 + tile_w, w))):
                slots.add(slot)
        occupied.append(slots)
    common = set.intersection(*occupied) if occupied else set()
    if common:
        slot = min(common)
        c0 = slot * pitch
        source_start, source_end = bands[0]
        # Copy the common tile into the 3-mask; leave all other mask cells 0.
        for dr, rr in enumerate(range(top, bottom + 1)):
            sr = source_start + dr
            if sr >= source_end:
                break
            for dc in range(tile_w):
                cc = c0 + dc
                if cc < w:
                    out[rr][cc] = grid[sr][cc]

    # Checkpoint cells lie on the repeated descending diagonal lattice.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 2 and (r + c) % 6 == 0:
                out[r][c] = 8
    return out

