        return out
    top, bottom = min(separators), max(separators)
    for r in range(top, bottom + 1):
        out[r] = [0] * w

    # The grid is arranged as 4x4 motifs on a 5-cell pitch. Reconstruct the
    # tile in the erased band from a neighboring motif at the same column.
    row_band = sum(1 for r in range(top) if r % 5 == 4)
    tile_row = top - 5 if top >= 5 else bottom + 1
    # Use the motif below the erased band when present, otherwise above it.
    if tile_row < 0 or tile_row + 4 > h - 1:
        tile_row = bottom + 1
    if tile_row + 4 <= h - 1:
        source_col = 0
        # A diagonal checkpoint determines the matching column. Select a
        # position whose (band,row) checkpoint is occupied in the motif.
        candidates = []
        for slot in range(4):
            c0 = 5 * slot
            if c0 + 3 < w and tile_row + row_band < h and c0 + slot < w:
                if grid[tile_row + row_band][c0 + slot] == 2:
                    candidates.append(slot)
        # The rightmost matching motif supplies the obscured continuation.
        target_slot = max(candidates) if candidates else 0
        source_col = 0
        if not any(any(grid[rr][cc] == 2 for rr in range(tile_row, tile_row + 4)
                       for cc in range(5 * s, min(5 * s + 4, w)))
                   for s in range(4)):
            tile_row = max(0, top - 5)
        for dr in range(min(4, bottom - top + 1)):
            for dc in range(4):
                tc = target_slot * 5 + dc
                sc = source_col + dc
                if tc < w and sc < w:
                    out[top + dr][tc] = grid[tile_row + dr][sc]

    # Mark the lattice checkpoints (band index, motif index) in each tile.
    for br, start in enumerate([r for r in range(h) if r % 5 == 0]):
        if top <= start <= bottom:
            continue
        for slot in range(4):
            rr, cc = start + br, slot * 5 + slot
            if rr < h and cc < w and out[rr][cc] == 2:
                out[rr][cc] = 8
    # Mark the inserted checkpoint as well.
    if top <= bottom and 'target_slot' in locals():
        rr, cc = top + row_band, target_slot * 5 + target_slot
        if rr < h and cc < w and out[rr][cc] == 2:
            out[rr][cc] = 8
    return out

