 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The patterns are arranged in equal square tiles separated by blank rows
    # and columns. Infer the pitch from the regularly spaced blank separators.
    blank_rows = [r for r, row in enumerate(grid) if all(v == 0 for v in row)]
    gaps = [b - a for a, b in zip(blank_rows, blank_rows[1:]) if b - a > 1]
    pitch = max(set(gaps), key=gaps.count) if gaps else (4 if h <= 11 else 5)
    tile_size = pitch - 1
    row_starts = list(range(0, h - tile_size + 1, pitch))
    col_starts = list(range(0, w - tile_size + 1, pitch))

    # Locate and clear the 3-colored occlusion stripe.
    mask_rows = [r for r, row in enumerate(grid) if all(v == 3 for v in row)]
    mask_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 0

    hidden = set()
    if mask_rows:
        for i, r0 in enumerate(row_starts):
            if any(r0 <= r <= r0 + tile_size - 1 for r in mask_rows):
                for j, c0 in enumerate(col_starts):
                    hidden.add((i, j))
    if mask_cols:
        for j, c0 in enumerate(col_starts):
            if any(c0 <= c <= c0 + tile_size - 1 for c in mask_cols):
                for i, r0 in enumerate(row_starts):
                    hidden.add((i, j))

    def tile_at(i, j):
        r0, c0 = row_starts[i], col_starts[j]
        if (i, j) in hidden:
            return None
        return tuple(tuple(grid[r0 + dr][c0 + dc] for dc in range(tile_size))
                     for dr in range(tile_size))

    # For a masked tile (i,j), infer its motif from the visible tiles in the
    # same tile-row or tile-column. Restore it only if its indexed checkpoint
    # (local row i, local column j) is a 2 in that motif.
    restored = {}
    for i, j in sorted(hidden):
        candidates = []
        if mask_cols:
            candidates.extend(tile_at(i, jj) for jj in range(len(col_starts)) if jj != j)
        if mask_rows:
            candidates.extend(tile_at(ii, j) for ii in range(len(row_starts)) if ii != i)
        candidates = [t for t in candidates if t and any(v == 2 for row in t for v in row)]
        if not candidates:
            candidates = [tile_at(ii, jj) for ii in range(len(row_starts))
                          for jj in range(len(col_starts)) if (ii, jj) not in hidden]
            candidates = [t for t in candidates if t and any(v == 2 for row in t for v in row)]
        if candidates:
            # Prefer the most frequent exact motif in the aligned neighbors.
            from collections import Counter
            motif = Counter(candidates).most_common(1)[0][0]
            if i < tile_size and j < tile_size and motif[i][j] == 2:
                restored[(i, j)] = motif
                r0, c0 = row_starts[i], col_starts[j]
                for dr in range(tile_size):
                    for dc in range(tile_size):
                        out[r0 + dr][c0 + dc] = motif[dr][dc]

    # Recolor each tile's designated indexed checkpoint (i,j) from 2 to 8.
    for i, r0 in enumerate(row_starts):
        for j, c0 in enumerate(col_starts):
            tile = restored.get((i, j), tile_at(i, j))
            if tile is None or i >= tile_size or j >= tile_size:
                continue
            if tile[i][j] == 2:
                out[r0 + i][c0 + j] = 8
    return out

