    out = [row[:] for row in grid]
    size, pitch = 4, 5
    row_starts = list(range(0, h - size + 1, pitch))
    col_starts = list(range(0, w - size + 1, pitch))

    # Clear the full-color occlusion band.
    mask_rows = [r for r, row in enumerate(grid) if len(row) == w and all(v == 3 for v in row)]
    mask_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 0

    # Extract the shared 4x4 motif from an unmasked tile, if available.
    tiles = {}
    hidden = set()
    for i, r0 in enumerate(row_starts):
        for j, c0 in enumerate(col_starts):
            if any(r0 <= r < r0 + size for r in mask_rows) or any(c0 <= c < c0 + size for c in mask_cols):
                hidden.add((i, j))
                continue
            tile = tuple(tuple(grid[r0 + dr][c0 + dc] for dc in range(size)) for dr in range(size))
            if any(v == 2 for row in tile for v in row):
                tiles[i, j] = tile

    # The symbol pattern repeats in each active tile. Restore masked tiles
    # where the same tile position is active in an adjacent unmasked band.
    for i, j in hidden:
        neighbors = [tile for (ii, jj), tile in tiles.items() if ii == i or jj == j]
        if not neighbors:
            neighbors = list(tiles.values())
        if not neighbors:
            continue
        from collections import Counter
        motif = Counter(neighbors).most_common(1)[0][0]
        r0, c0 = row_starts[i], col_starts[j]
        # Restore only when this row/column of the repeated array contains a motif.
        active = any((ii == i or jj == j) for ii, jj in tiles)
        if active:
            tiles[i, j] = motif
