    h, w = len(grid), len(grid[0])
    mask_rows = [r for r, row in enumerate(grid) if all(v == 3 for v in row)]
    mask_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    stripe = mask_rows if mask_rows else mask_cols
    if stripe:
        size = max(stripe) - min(stripe) + 1
    else:
        size = 4 if h >= 15 else 3
    pitch = size + 1
    out = [row[:] for row in grid]

    # Find the repeated tile motif among all intact lattice positions.
    rstarts = list(range(0, h - size + 1, pitch))
    cstarts = list(range(0, w - size + 1, pitch))
    motifs = []
    for r0 in rstarts:
        for c0 in cstarts:
            tile = tuple(tuple(grid[r0 + dr][c0 + dc] for dc in range(size))
                         for dr in range(size))
            if any(v == 2 for row in tile for v in row):
                motifs.append(tile)
    if not motifs:
        return [[0 if v == 3 else v for v in row] for row in grid]
    motif = Counter(motifs).most_common(1)[0][0]

    # Clear all occlusion cells, and reconstruct the macro-tile array from
    # the motif's own 2-mask: macro-position (i,j) is occupied iff motif[i][j]=2.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 0
    nrows = len(rstarts)
    ncols = len(cstarts)
    for i in range(nrows):
        for j in range(ncols):
            r0, c0 = rstarts[i], cstarts[j]
            occupied = i < size and j < size and motif[i][j] == 2
            for dr in range(size):
