                    rr, cc = r0 + dr, c0 + dc
                    if rr < h and cc < w:
                        out[rr][cc] = motif[dr][dc] if occupied else 0
            if occupied:
                rr, cc = r0 + i, c0 + j
                if rr < h and cc < w and out[rr][cc] == 2:
